"""Human-readable reasons for missing values; never fabricate statistical tests."""
from pathlib import Path
from collections import Counter
from .io import read_json,write_json,versions
from .dataset import audit
from .preflight import preflight


def number(value):return 'Not estimable' if value is None else f'{value:.4f}'


def report(config,bundle=None):
    if bundle is None:bundle=read_json(Path(config.output_dir)/'results/analysis.json')
    directory=Path(config.output_dir)/'results';source=bundle['source'];meta=bundle['metadata']
    embedding_layers={r['layer'] for r in meta['layers'] if r.get('kind')=='embedding'}
    primary=[r for r in bundle['comparisons'] if r['analysis_role']=='primary' and r['layer'] not in embedding_layers]
    outcomes=[]
    for row in primary:
        r=dict(row)
        if source=='synthetic_validation':outcome='synthetic_validation_only'
        elif r['difference_reasoning_minus_facts'] is None:outcome='estimate_undefined_see_diagnostics'
        elif r['ci_low'] is None:outcome='uncertainty_unavailable_see_flags'
        elif r['adjusted_p_value'] is None:
            outcome='conditional_interval_above_zero' if r['ci_low']>0 else ('conditional_interval_below_zero' if r['ci_high']<0 else 'conditional_interval_includes_zero')
        elif r['adjusted_p_value']>=.05:outcome='no_rejection_of_null_not_equivalence'
        else:outcome='positive_association_under_test_assumptions' if r['difference_reasoning_minus_facts']>0 else 'negative_association_under_test_assumptions'
        outcomes.append({**r,'outcome':outcome})
    counts=dict(Counter(r['status'] for r in bundle['estimates']))
    expected=[r for r in bundle['estimates'] if r['layer'] in embedding_layers and r['status']!='ok']
    flagged=[r for r in bundle['estimates'] if r['layer'] not in embedding_layers and r['status']!='ok']
    design=preflight(meta['rows'],config) if source=='model' and config.require_preflight else None
    summary={'research_question':'Do reasoning prompts occupy higher-dimensional representation clouds than factual recall?','source':source,'scientific_model_findings_available':source=='model','primary_estimator':'pr','primary_contrast':'reasoning minus facts','primary_split':bundle['analysis_config']['split'],'primary_outcomes':outcomes,'hypothesis_supported':None,'formal_significance_testing':'not_performed_no_exchangeability_design' if not config.permutation_exchangeable else 'opt_in_cluster_permutation_assumptions_required','model':meta['model'],'dataset_audit':audit(meta['rows']),'preflight':design,'preprocessing':bundle['analysis_config']['preprocessing'],'length_matching':bundle['length_matching'],'estimate_status_counts':counts,'expected_noninformative_embedding_estimates':expected,'flagged_block_estimates':flagged,'failed_or_unstable_estimates':expected+flagged,'fdr':'BY for valid opt-in p-values; not applied when no significance tests are performed','analysis_fingerprint':bundle['analysis_fingerprint'],'software':meta['software'],'report_software':versions(),'configuration':bundle['analysis_config']}
    write_json(directory/'results_summary.json',summary)
    dataset_audit=summary['dataset_audit'];cfg=bundle['analysis_config']
    text=['# Representation geometry research report','', '**SYNTHETIC VALIDATION — NO MODEL FINDINGS**' if source=='synthetic_validation' else '**Measured model activations; observational, conditional inference.**','', '## Question and hypotheses','H1 compares reasoning versus factual recall by participation ratio. H2 concerns task spectra, H3 layer variation and H4 robustness under controls. No task ordering is assumed.','','## Model and extraction',f"Model: `{meta['model'].get('model_id')}`; resolved revision: `{meta['model'].get('resolved_revision')}`; actual device: `{meta['model']['device']}`; dtype: `{meta['model']['dtype']}`.",meta['convention'],'For Qwen, tuple index 0 is the embedding and 1..28 are blocks; the last output includes RMSNorm. Synthetic layers have no transformer interpretation.','','## Dataset and controls',f"Total prompts: {len(meta['rows'])}. Selected split: {cfg['split']}.",'| Task | Total prompts | Evaluation prompts | Evaluation families |','|---|---:|---:|---:|']
    for c,info in dataset_audit['categories'].items():text.append(f"| {c} | {info['count']} | {info['splits'].get('evaluation',0)} | {info['families_per_split']['evaluation']} |")
    text+=['Fixed source-linked factual fixtures, exact arithmetic, explicitly checked logical rules and Python literal predictions provide ground truth. Human ambiguity review is still pending. Named task families are operational clusters, not proof of independence. Shared operators, vocabulary, factual entities, answer types and domain diversity remain confounds.',f"Length matching: {bundle['length_matching']}. IDs and family coverage are preserved in `selection.json` and preflight output. Four-token bins permit residual within-bin differences; this is not perfect matching. Compare length matching against both `length_count_control` (same N) and `length_family_control` (same N and per-family composition), rather than attributing an 80-versus-52 sample difference to length alone. The 2D PCA basis is fitted on exploratory prompts only."]
    if design:text += [f"Design preflight: **{design['status']}**. Counts: {design['counts']}."]
    text+=['','## Methods','Raw centered covariance is primary. Eigenvalues σ²/(N−1) come from full economy float64 SVD; at most min(N−1,d) centered directions are identifiable. PR=(Σλ)²/Σλ². Covariance effective rank=exp(−Σp log p). PCA 80/90/95/99% thresholds are separate spectral summaries. TWO-NN is a local Euclidean neighbor-ratio CDF fit; duplicates and poor fit are explicit diagnostics. Unit normalization and feature standardization change geometry and are separately labeled. Bootstrap functionals use the equivalent small Gram covariance spectrum for efficiency, not for numerical-rank inference.','', '## Primary block comparisons','Embedding output is a diagnostic only and is excluded from primary block inference. If the common final prompt token has zero variance, its dimensionality is mathematically undefined; this is expected, not extraction failure.','| Block | PR: reasoning minus facts | Conditional bootstrap interval | Adjusted p | Interpretation |','|---|---:|---|---|---|']
    for r in outcomes:
        interval=f"[{number(r['ci_low'])}, {number(r['ci_high'])}]" if r['ci_low'] is not None else 'Not estimated; see flags'
        p=number(r['adjusted_p_value']) if r['adjusted_p_value'] is not None else 'Not performed'
        text.append(f"| {r['layer_label']} | {number(r['difference_reasoning_minus_facts'])} | {interval} | {p} | {r['outcome'].replace('_',' ')} |")
    text+=['','## Why tests or estimates may be absent','**Not performed** means no defensible task-family exchangeability design was supplied, so a permutation p-value was deliberately not computed. Increasing family count alone does not justify label permutations. The report does not treat conditional percentile intervals as automatically calibrated significance tests. `hypothesis_supported` remains null without a defensible testing design.','**Not estimated** intervals can arise from insufficient retained families, zero variance or disabled resampling modes. **Not estimable** dimensions arise from zero variance, duplicate neighborhoods or inadequate samples. Each reason is available in flags and diagnostics. JSON retains nulls for machine-readable missing values; this report explains them.',f"Bootstrap replicates: {cfg['bootstrap']}; uncertainty modes: {cfg.get('uncertainty_modes',['raw'])}; minimum families: {cfg['min_families']}. Resampling samples complete observed families, refits preprocessing and can vary prompt count. Intervals condition on the selected empirical family population and assumed independent clusters; source/operator/entity dependence can invalidate that assumption. More resamples do not create more independent units.",'TWO-NN replacement-bootstrap intervals are intentionally disabled because repeated points invalidate neighbor geometry. Subsampling ranges are descriptive sensitivity checks. BY correction is applied only to valid opt-in tests, with primary PR and secondary/robustness families separated.','','## Diagnostics and robustness',f"Status counts: {counts}. Expected noninformative embedding entries: {len(expected)}. Other flagged block entries: {len(flagged)}. Flags may describe poor-fit or unavailable local geometry, not corrupted extraction.",'`estimates.csv` contains all task/layer/metric values; `comparisons.csv` contains primary and control contrasts, uncertainty and flags. `pairwise_comparisons.csv` contains descriptive all-task pair differences. `spectra.csv`, `robustness.csv`, `projections.csv`, `diagnostics.json`, `selection.json` and `preflight.json` (when enforced) preserve source data. Figure 5 shading is subsampling range, not confidence.','','## Interpretation and limits','A conditional interval above or below zero describes uncertainty under the family-resampling assumptions; it does not automatically establish a population-wide reasoning effect or significance. The revised study was designed after the legacy pilot; preserve both as separate runs, freeze the revised dataset/configuration before extracting new evaluation activations, and record deviations. Task labels, domain breadth and template counts alone do not establish exchangeability or independence. Human review, alternative operationalizations and model replication are still needed.','Dimensionality does not establish causal mechanisms, computational effort, reasoning ability, representational content or model answer correctness. The primary experiment generates no answers. No result is predetermined. Synthetic validation checks software only.','','## Reproducibility',f"Analysis fingerprint: `{bundle['analysis_fingerprint']}`. Metadata preserve sample IDs, seeds, dtype, resolved revision, software and source fingerprints.",'Figures are 600-DPI PNG by default plus vector PDF/SVG and source CSVs. Notebook previews are scaled. ZIP exports exclude weights and, by default, activation arrays; preserve arrays separately for reanalysis.']
    (directory/'research_report.md').write_text('\n'.join(text)+'\n')
    return summary
